import{_ as t,H as a,f as i,i as l}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"41 | 内功心法（二）：内核和后端通用的设计思想有哪些？","description":"","frontmatter":{},"headers":[{"level":2,"title":"内功心法之池化","slug":"内功心法之池化","link":"#内功心法之池化","children":[{"level":3,"title":"内存池","slug":"内存池","link":"#内存池","children":[]},{"level":3,"title":"连接池","slug":"连接池","link":"#连接池","children":[]},{"level":3,"title":"线程池","slug":"线程池","link":"#线程池","children":[]}]},{"level":2,"title":"内功心法之分层","slug":"内功心法之分层","link":"#内功心法之分层","children":[]},{"level":2,"title":"内功心法之缓存","slug":"内功心法之缓存","link":"#内功心法之缓存","children":[]},{"level":2,"title":"重点回顾","slug":"重点回顾","link":"#重点回顾","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"计算机基础实战课/41｜内功心法（二）：内核和后端通用的设计思想有哪些？.md","filePath":"计算机基础实战课/41｜内功心法（二）：内核和后端通用的设计思想有哪些？.md","lastUpdated":1795560006000}'),p={name:"计算机基础实战课/41｜内功心法（二）：内核和后端通用的设计思想有哪些？.md"};function n(s,e,E,r,o,h){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_41-内功心法-二-内核和后端通用的设计思想有哪些" tabindex="-1">41 | 内功心法（二）：内核和后端通用的设计思想有哪些？ <a class="header-anchor" href="#_41-内功心法-二-内核和后端通用的设计思想有哪些" aria-label="Permalink to &quot;41 | 内功心法（二）：内核和后端通用的设计思想有哪些？&quot;">​</a></h1><p>你好，我是 LMOS。</p><p>上节课，我们学习了并行化、异步化、调度思想这三种内功心法，无论是内核设计还是后端场景里，你总能找到这些“心法”的影子。看完以后是不是感觉有点意犹未尽？</p><p>这节课，我再给你分享三种设计思想，分别是池化、分层和缓存。无论是操作系统内核，还是后端当中，这三种设计思想也是通用的。这两节课属于偏抽象的架构思想，因此建议你学完之后结合自己的具体工作实践进一步理解、消化。好，让我们进入正题。</p><h2 id="内功心法之池化" tabindex="-1">内功心法之池化 <a class="header-anchor" href="#内功心法之池化" aria-label="Permalink to &quot;内功心法之池化&quot;">​</a></h2><p>如果你是一家水果店的店长，肯定要走批发采购、平时贩卖零售的路线。要是有顾客来选购一种水果的时候，我们才去采购、运输过来实在是费事费力，太过低效。但如果我们提前采购好一批水果，顾客来购买的时候我们直接拿给顾客，这样就可以有效节约时间和运输成本。</p><p>这种降低开销的思路，在工程中也是类似的。为了提升资源（计算、存储、网络）的复用性、避免重复创建的开销，我们通常会提前统一创建一批资源，放入资源池，在使用时直接向资源池申请，使用完毕之后再归还给资源池，这样的思路我们称为池化思想。</p><p>之前讲内存管理的时候，我们提到过，为了减少内存分配或销毁时的时间开销，避免内存碎片的产生，我们会维护一个内存链表。</p><p>当编程语言申请内存的时候，OS 内核就会根据内存分配算法，在链表中查找一段可以分配的内存分配出去。等到内存需要释放的时候，不但需要进行查找、释放操作，还需要整理，这些操作都比较耗时。怎么解决这个问题呢？</p><p>答案就是内存池技术，我们可以提前申请一大块内存来进行统一管理，然后每次需要分配内存时，都从这块内存中取出，并标记下这块内存被用了，释放时标记此内存被释放了。请注意，释放时，并不是真的把内存释放给了操作系统。只有等到一大块内存都空闲的时候，才会释放给操作系统。这样，就减少了分配、释放的操作次数，从而提高了效率。</p><p>后端领域中，我们也会经常使用池化思想。比如内存池、链接池、线程池等等，都是后端常用的池化思想的工程应用方式。</p><h3 id="内存池" tabindex="-1">内存池 <a class="header-anchor" href="#内存池" aria-label="Permalink to &quot;内存池&quot;">​</a></h3><p>我们先从内存池说起。其实内存池也我们的老朋友了，因为之前讲Golang 内存管理时学过，编程语言运行时库中也会实现内存池。其实 Golang 的内存池的设计也是借鉴了TCMalloc 内存池的管理思路。</p><p>为了更好地理解内存池的设计思路，首先让我们来看一下 TCMalloc 的架构设计吧：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/1.png" alt=""></a></p><ul><li>图片来源：<a href="https://github.com/google/tcmalloc/blob/master/docs/design.md#overview" target="_blank" rel="noreferrer">https://github.com/google/tcmalloc/blob/master/docs/design.md#overview</a></li></ul><p>Back-end 会向操作系统申请内存，当用户代码使用 TCMalloc 内存池时则会复用 Back-end 申请的内存。内存不够的时候，TCMalloc 还会继续向操作系统申请更多内存；在用户代码释放内存的时候，TCMalloc 也会主动进行内存回收。</p><h3 id="连接池" tabindex="-1">连接池 <a class="header-anchor" href="#连接池" aria-label="Permalink to &quot;连接池&quot;">​</a></h3><p>接着我们说说连接池。连接池的作用是管理链接的创建和销毁，以及复用链接。从事后端开发的同学，最常见的可能就是数据库连接池了，那我们为什么要使用数据库连接池呢？</p><p>要解答这个问题，我们可以先设想一下如果没有连接池，一次查询 MySQL 都会经历哪些步骤：</p><p>第一步，建立链接，MySQL 协议是基于 TCP 的，所以 MySQL Client 和 MySQL Server 端建立链接的时候，也会经历 TCP 的三次握手。</p><p>第二步是认证环节。记不记得，我们链接 MySQL 的时候还指定了帐号密码？没错，这里我们还需要进行认证。根据 MySQL 官方文档中的协议章节，我们可以把认证部分大概细分成以下三个部分：</p><ul><li><p>服务端向客户端发送密钥；</p></li><li><p>客户端使用密钥加密用户名、密码等信息，然后再把加密后的包发给服务端（这样可以防止被中间人盗取到明文帐号密码）；</p></li><li><p>服务端再根据客户端发送过来的包，验证是否是合法的帐号密码，然后给客户端响应认证结果。</p></li></ul><p>第三步，客户端发送需要执行的 SQL 语句。</p><p>第四步，服务端返回该 SQL 语句的执行结果。</p><p>第五步，MySQL 执行完毕，触发关闭操作。</p><p>第六步，TCP 链接随之断开，这时候就会经历“四次分手”啦。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/2.png" alt=""></a></p><ul><li>流程图</li></ul><p>我们发现，整个过程中如果不使用连接池复用连接，每执行一条 SQL 语句就会在网络 IO、认证之类的事情上浪费很多资源和时间。但如果使用连接池，复用了这些连接的话，就只需要执行 SQL 语句的请求响应开销了，这显然是一个不错的思路。</p><p>其实连接池在后端中很常用，比如 Java 的 httpclient、Golang 的 net/http 包中都在使用连接池的思想来提升 HTTP 请求的性能。如果对这些有兴趣，你可以课后自行探索。</p><h3 id="线程池" tabindex="-1">线程池 <a class="header-anchor" href="#线程池" aria-label="Permalink to &quot;线程池&quot;">​</a></h3><p>线程中执行的就是我们写的应用程序，在后端领域中，为了提升响应速度，我们经常会为每一个请求分配一个独立的线程来处理。不过别忘了，线程的创建、销毁、调度都是有开销的，所以当我们创建的线程比较多的时候，系统性能也有可能会下降。</p><p>这时候，还得继续引入我们的池化思想，开启“复用大法”。思路是这样的：我们可以通过提前创建一批线程，当需要使用的时候直接从里面取一个“现成的”线程，用完之后归还。</p><p>没错，Java J.U.C 中 ThreadPoolExecutor 线程池的核心设计思路也是类似的，你可以点击文稿中的简化版 ThreadPoolExecutor 线程池的设计图来对照理解一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/3.png" alt=""></a></p><h2 id="内功心法之分层" tabindex="-1">内功心法之分层 <a class="header-anchor" href="#内功心法之分层" aria-label="Permalink to &quot;内功心法之分层&quot;">​</a></h2><p>计算机科学家 Butler Lampson 有一句名言：All problems in computer science can be solvedby another level of indirection.</p><p>说的是在计算机科学中，所有问题都可以通过引入一个分层来解决。分层可以有效控制系统的复杂性、简化系统设计，让不同的人专注做某一层次的事情。</p><p>想象一下，如果你要设计一款网络程序，却没有分层，该是一件多么痛苦的事情，因为这要求你必须是一个通晓网络的全才：要知道各种网络设备的接口是什么样的，以便将数据包发送给它；要关注数据传输的细节；还需要处理类似网络拥塞，数据超时重传这样的复杂问题；当然了，你更需要关注数据如何在网络上安全传输，避免数据被别人窥探和篡改。</p><p>而有了分层的设计，你只需要专注设计应用层的程序就可以了。其他的问题，都可以交给下面几层来完成。</p><p>分层之后，有些层具有很高的复用性，可以提升工程效率。比如，我们在设计系统 A 的时候，发现某一层具有一定的通用性，那么我们可以把它抽取独立出来，在设计系统 B 的时候用起来，这样可以减少研发周期，提升研发的效率。</p><p>分层架构还更容易做横向扩展。很多时候如果系统没有一个好的分层，流量增加时，我们就需要对整个系统进行扩展了，这样开销其实是比较大的。</p><p>举个例子，比如有一段代码里面需要进行图形图像计算，这时候 CPU 开销可能会比较高。</p><p>如果没有分层，代码和业务逻辑耦合在了一起，就需要扩容整个服务，这显然是没必要的开销。但如果我们做了合理的分层，把计算密集型的代码全部收敛到同一层，这样进行扩展时，我们就可以轻松抽离这部分代码，这不但节约了资源，还提升了系统的可维护性和可扩展性。</p><p>操作系统里处处可见分层思想。比如 Linux 内核中，对网络部分就是按照网络协议层、网络设备层、设备驱动功能层和网络媒介层这个分层体系来设计的。这样设计的好处是，网络驱动功能层主要通过网络驱动程序实现。这种分层结构与网络协议的结构匹配，既能简化数据包处理流程，又便于扩展和维护。</p><p>除了内核系统，后端开发里分层也很常见。根据《阿里巴巴 Java 开发手册》中的建议，我们可以看到后端项目常用的分层模式如下图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/4.png" alt=""></a></p><p>对照示意图，我们分别看看不同层起到的作用。</p><p>终端显示层，这一层主要用于各端模板渲染并执行显示的层。当然，前后端分离之后，这个层有时候也会被前端技术栈所接管。开放接口层用于将 Service 层方法封装成开放的接口，同时进行网关安全控制以及流量控制等工作。</p><p>接着是请求处理层，也就是 Web 层，主要是对访问控制进行转发，做一些基础的参数校验和一些简单的业务处理工作。再往下是 Service 层，用于承载主要的业务逻辑。</p><p>之后是通用业务处理层，也可以叫 Manager 层。这一层主要有两点要注意。首先，你可以将原先 Service 层的一些通用的能力（比如与缓存和存储交互策略、中间件的接入）放到这一层；其次，你也可以在这一层封装对第三方接口的调用，比如调用支付服务，调用审核服务等。</p><p>接下来是数据访问层，我们通常叫它 DAO 层，用来与底层 MySQL、Redis、MongoDB、Elasticsearch、HBase 等数据库进行数据交互。</p><p>最后还有外部接口或第三方平台，包括其它部门的 RPC 开放接口、基础平台、其它公司的HTTP 接口。</p><h2 id="内功心法之缓存" tabindex="-1">内功心法之缓存 <a class="header-anchor" href="#内功心法之缓存" aria-label="Permalink to &quot;内功心法之缓存&quot;">​</a></h2><p>在计算机系统中，我们经常会遇到读写速度不匹配的场景。为了解决内存读写速度不匹配的问题，能不能把一部分常用的数据，放在读取速度更快的存储空间里呢？这个想法就是缓存思想的雏形。</p><p>当然引入了缓存之后，在传递的过程中，缓存数据和原始数据可能会因为各种原因导致不一致，这又引入了缓存一致性的问题。</p><p>在 SMP 系统中，处理器的每个核都有独立的一级缓存，因此同一内存位置的数据，可能在多个核一级缓存中存在多个副本，所以存在数据一致性的问题。目前主流的缓存一致性协议是MESI 协议及其衍生协议。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/5.png" alt=""></a></p><p>为了维护缓存一致性，处理器之间需要通信，MESI 协议提供了以下消息：</p><ul><li><p>Read 读：包含想要读取的缓存行的物理地址。</p></li><li><p>Read Response 读响应：包含读消息请求的数据。读响应消息可能是由内存控制器发送的，也可能是由其他处理器的缓存发送的。如果一个处理器的缓存行有想要的数据，并且处于修改状态，那么必须发送读响应消息。</p></li><li><p>Invalidate 使无效：包含想要删除的缓存行的物理地址。所有其他处理器必须从缓存行中删除对应的数据，并且发送使无效确认消息来应答。</p></li><li><p>Invalidate Acknowledge 使无效确认：处理器收到使无效消息，必须从缓存行中删除对应的数据，并且发送使无效确认应答消息。</p></li><li><p>Read Invalidate 读并且使无效：包含想要读取的缓存行的物理地址，同时要求从其他缓存中删除数据。它是读消息和使无效消息的组合 ，需要接收者发送读响应消息和使无效确认消息。</p></li><li><p>Writeback 写回：包含想要写回到内存的地址和数据。</p></li></ul><p>由此我们看到，为了保证缓存在各处理器间的一致性，需要进行核间消息的处理。因此即使像原子变量这种看似没有消耗的同步机制，也是有开销的。</p><p>缓存思想在后端中也十分常用，根据应用场景，我们可以大致把缓存分为四大类：第一类，CDN 缓存。CDN 即内容分发网络，CDN 边缘节点会将数据缓存起来；第二类是反向代理缓存，比如 Nginx 的缓存；第三类是本地缓存，典型例子有 Caffeine Cache 和 Guava Cache；最后就是分布式缓存，Redis 等各种缓存系统都归属于这一类。</p><h2 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">​</a></h2><p>这节课，我们主要学习了池化、分层和缓存这三种思想。我来带你回顾下重点。</p><p>内存池、链接池、线程池等等，都是后端常用的池化思想的工程应用方式，这可以帮助我们复用资源、提高资源使用效率。</p><p>分层思想可以让复杂项目的结构变得更清晰，学过业界常用的后端项目设计规范之后，我想你更能体会到这一点。</p><p>缓存思想则告诉我们可以通过缓存提高数据读取性能，解决内存读写速度不匹配的问题。不过另一方面，这可能引入缓存一致性的风险。因此在实际工程应用的时候，我们一定要仔细权衡。</p><p>我还把这节课的要点画成了导图，供你参考：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/41/6.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这节课，我们学习了池化、分层、缓存这三招内功心法，请你思考一下在你的日常工作中有没有哪里用到了这几类设计思想呢？</p><p>欢迎你在留言区跟我一起交流，如果这节课对你有启发，别忘了分享给身边更多朋友。</p>',73)])])}const g=t(p,[["render",n]]);export{A as __pageData,g as default};
